**Decorator (Dekoratör)**: Bir fonksiyona, onu değiştirmeden yeni işlevsellik ekleyen yapıdır.

```python
import time
from functools import wraps

# 1. Temel Decorator - Zamanlama
def timer(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        start = time.time()
        result = func(*args, **kwargs)
        end = time.time()
        print(f"{func.__name__} çalışma süresi: {end-start:.4f}s")
        return result
    return wrapper

@timer
def yavaş_fonksiyon():
    time.sleep(1)
    return "Bitti!"

yavaş_fonksiyon()  # "yavaş_fonksiyon çalışma süresi: 1.0012s"

# 2. Parametreli Decorator - Retry
def retry(max_attempts=3):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(max_attempts):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    print(f"Deneme {attempt+1}/{max_attempts} başarısız: {e}")
            raise Exception(f"{max_attempts} deneme başarısız")
        return wrapper
    return decorator

@retry(max_attempts=3)
def api_cagir():
    # API çağrısı...
    pass
```

**Yaygın kullanımlar**: Loglama, caching, yetkilendirme, Flask route'ları (`@app.route`)
